use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n < list.len(),
    ensures
        new_list.len() == list.len(),
        // Elements from n to end appear first
        forall|i: int| 0 <= i < (list.len() - n) as int ==> 
            new_list[i] == list[n as int + i],
        // Elements from 0 to n-1 appear at the end
        forall|i: int| (list.len() - n) as int <= i < list.len() as int ==> 
            new_list[i] == list[i - (list.len() - n) as int],
{
    let mut result = Vec::new();
    let mut idx: usize = n;
    
    // First phase: copy elements from index n to the end
    while idx < list.len()
        invariant
            n <= idx <= list.len(),
            result.len() == idx - n,
            forall|i: int| 0 <= i < result.len() ==> 
                result[i] == list[n as int + i],
    {
        result.push(list[idx]);
        idx = idx + 1;
    }
    
    // Second phase: copy elements from index 0 to n-1
    idx = 0;
    while idx < n
        invariant
            0 <= idx <= n,
            n < list.len(),
            result.len() == (list.len() - n) + idx,
            // First part remains unchanged
            forall|i: int| 0 <= i < (list.len() - n) as int ==> 
                result[i] == list[n as int + i],
            // Second part being built
            forall|i: int| (list.len() - n) as int <= i < result.len() ==> 
                result[i] == list[i - (list.len() - n) as int],
    {
        result.push(list[idx]);
        idx = idx + 1;
    }
    
    result
}

} // verus!